// ── Customer-service 15-minute gate ──────────────────────────────
// Input:  rows from the "Get a row" (Notification) node for this client.
// Output: one item; shouldNotify = true ONLY if the last customer_service
//         notification is older than 15 minutes (or none exists).

const WINDOW_MINUTES = 15;

// Collect rows (handles "one item per row" AND "array inside one item")
let rows = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j)) rows.push(...j);
  else if (j) rows.push(j);
}

// Keep only customer_service rows that actually have a timestamp
rows = rows.filter(r => r && r.createdAt && r.type === 'customer_service');

// Newest first
rows.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

const latest = rows[0] || null;

let minutesSince = null;
let shouldNotify = true;                       // no previous request → allow

if (latest) {
  const ageMs = Date.now() - new Date(latest.createdAt).getTime();
  minutesSince = Math.floor(ageMs / 60000);
  shouldNotify = ageMs >= WINDOW_MINUTES * 60 * 1000;
}

return [{
  json: {
    shouldNotify,                 // TRUE  → create the notification (ping staff)
    throttled: !shouldNotify,     // TRUE  → within 15 min → skip the ping
    minutesSince,                 // minutes since last request (null = none)
    windowMinutes: WINDOW_MINUTES,
    latestCreatedAt: latest ? latest.createdAt : null,
    lastNotificationId: latest ? latest.id : null,
    totalFound: rows.length,
  }
}];

